1	"""Contrast, measured against the real background each string sits on.
2	
3	Two traps this avoids:
4	  * Tailwind 4 emits oklch(); a regex that only understands rgb() silently
5	    reads "oklch(0.208 0.042 265)" as rgb(0,208,0) and reports nonsense. Every
6	    colour is normalised through a canvas first.
7	  * Text over a photo or video has no token background at all. Those are split
8	    out and must be judged on pixels, not on computed style.
9	"""
10	from playwright.sync_api import sync_playwright
11	
12	JS = """() => {
13	  // Draw the colour and read the pixel back. Setting fillStyle alone is not
14	  // enough: Chromium hands oklch() straight back as the same string, so any
15	  // hex/rgb parser downstream produces NaN. Rasterising forces the conversion
16	  // and works for every colour space the page can name.
17	  const el0 = document.createElement('canvas');
18	  el0.width = el0.height = 1;
19	  const cv = el0.getContext('2d', { willReadFrequently: true });
20	  const rgbOf = (c) => {
21	    cv.clearRect(0, 0, 1, 1);
22	    cv.fillStyle = c;
23	    cv.fillRect(0, 0, 1, 1);
24	    const d = cv.getImageData(0, 0, 1, 1).data;
25	    return [d[0], d[1], d[2]];
26	  };
27	  const norm = (c) => { const [r, g, b] = rgbOf(c); return `rgb(${r},${g},${b})`; };
28	  const lum = (c) => {
29	    const [r, g, b] = rgbOf(c).map(v => v / 255)
30	      .map(v => v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
31	    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
32	  };
33	  const ratio = (a, b) => {
34	    const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
35	    return (x + 0.05) / (y + 0.05);
36	  };
37	  const opaque = (bg) => bg && bg !== 'transparent' && !/rgba\\(0, 0, 0, 0\\)/.test(bg);
38	  // Walk up for a background. Returns null when a photo/video ancestor is hit
39	  // first: that string is over media and computed style cannot answer it.
40	  const groundOf = (el) => {
41	    let n = el;
42	    while (n && n !== document.documentElement) {
43	      const cs = getComputedStyle(n);
44	      if (n.querySelector && n.querySelector(':scope > video, :scope > img')) {
45	        const r = n.getBoundingClientRect(), e = el.getBoundingClientRect();
46	        if (e.top >= r.top - 1 && e.bottom <= r.bottom + 1) return null;
47	      }
48	      if (opaque(cs.backgroundColor)) return cs.backgroundColor;
49	      n = n.parentElement;
50	    }
51	    return 'rgb(255,255,255)';
52	  };
53	  const rows = [], overMedia = [], seen = new Set();
54	  document.querySelectorAll('body *').forEach(el => {
55	    if (el.closest('script, style')) return;
56	    const hasText = [...el.childNodes].some(n => n.nodeType === 3 && n.textContent.trim());
57	    if (!hasText) return;
58	    const cs = getComputedStyle(el);
59	    const size = parseFloat(cs.fontSize), weight = parseInt(cs.fontWeight) || 400;
60	    const ground = groundOf(el);
61	    const sample = el.innerText.trim().slice(0, 24).replace(/\\s+/g, ' ');
62	    if (ground === null) { if (!seen.has('m' + sample)) { seen.add('m' + sample); overMedia.push({ sample, size: Math.round(size) }); } return; }
63	    const key = cs.color + '|' + ground + '|' + Math.round(size);
64	    if (seen.has(key)) return;
65	    seen.add(key);
66	    const large = size >= 24 || (size >= 18.66 && weight >= 700);
67	    const r = ratio(cs.color, ground);
68	    rows.push({ sample, size: Math.round(size), color: norm(cs.color), ground: norm(ground),
69	                ratio: Math.round(r * 100) / 100, floor: large ? 3 : 4.5, pass: r >= (large ? 3 : 4.5) });
70	  });
71	  return { rows, overMedia };
72	}"""
73	
74	with sync_playwright() as p:
75	    b = p.chromium.launch()
76	    pg = b.new_page(viewport={'width': 1440, 'height': 900})
77	    pg.goto('http://localhost:3055/', wait_until='networkidle')
78	    pg.wait_for_timeout(1500)
79	    res = pg.evaluate(JS)
80	    for r in sorted(res['rows'], key=lambda x: x['ratio']):
81	        mark = 'FAIL' if not r['pass'] else 'ok  '
82	        print(f"{mark} {r['ratio']:>6}:1 (golv {r['floor']}) {r['size']:>3}px {r['color']} pa {r['ground']}  {r['sample']!r}")
83	    fails = [r for r in res['rows'] if not r['pass']]
84	    print(f"\n{len(res['rows'])} tokenbakgrunder, {len(fails)} under golvet")
85	    print(f"{len(res['overMedia'])} strangar ligger over foto/video och maste bedomas pa pixlar:")
86	    for m in res['overMedia']:
87	        print(f"    {m['size']:>3}px {m['sample']!r}")
88	    b.close()
