156	
157	  *{box-sizing:border-box;}
158	  html,body{margin:0;overflow-x:clip;}
159	  body{position:relative;background:var(--c-black);color:#f4f2ef;
160	    font-family:var(--font);font-weight:300;font-size:16px;line-height:1.5;
161	    -webkit-font-smoothing:antialiased;}
162	  img{max-width:100%;display:block;}
163	  a{color:inherit;}
164	  h1,h2,h3,p,figure{margin:0;}
165	
166	  /* Fokusringen har ETT VÄRDE PER GRUND. Mätt: #1e5e9c mot #0b0c0e ger 2,93:1
167	     och underkänns mot WCAG 1.4.11:s 3:1. #f4f2ef mot #0b0c0e ger 17,5:1.
168	     Accenten är därmed också befriad från sin tredje förekomst. */
169	  :focus-visible{outline:2px solid #f4f2ef;outline-offset:2px;}
170	  .on-paper :focus-visible{outline-color:var(--ink);}
171	
172	  /* ============================================================ grunden
173	     Ett enda fotografi bär hela sidan. Fixed, gråskala, tonad av motorns
174	     --sc-canvas-drift i tre stopp. Ingen andra bakgrundsbild finns.
175	     background-attachment:fixed är BORTTAGET mot V3b: elementet är redan
176	     position:fixed, så attachmentet var en ren repaint-kostnad utan effekt. */
177	  /* Tonen ligger som ett eget bakgrundslager PÅ grunden och blandas med
178	     `background-blend-mode`, som bara blandar elementets egna lager, i stället
179	     för V3b:s `::after` i `mix-blend-mode: color`, som läser sidans backdrop.
180	     `transition: background 1.1s` är borttagen: motorn interpolerar redan
181	     --sc-canvas kontinuerligt, så transitionen målade om ett helskärmslager i
182	     1,1 s efter varje drift-steg utan att synas.
183	
184	     contain:strict är MÄTT FRAM, inte gissad. Attribution vid 4x CPU,
185	     `motion_probe --wheel 100:60`, p95 i ms:
186	       som byggd .............................. 33,4
187	       utan filter ............................ 33,3   filtret var inte felet
188	       utan background-blend-mode ............. 33,4   blandningen var inte felet
189	       utan filter OCH blend .................. 33,3   inte heller tillsammans
190	       .ground display:none ................... 16,8   grunden ÄR felet
191	       .ground + will-change:transform ........ 33,4   promovering gör det VÄRRE
192	       .ground + contain:strict ............... 16,8   rätt verktyg
193	     Kostnaden var att ett helskärmsstort fast raster målades om per hjulhack,
194	     inte att det var filtrerat eller blandat. `contain: strict` är sant om det
195	     här elementet: storleken kommer ur inset:0 och inte ur innehållet, det har
196	     inga barn, och det målar bara i sin egen ruta. Raden är samtidigt belägget
197	     för performance.md:s förbud mot vilande `will-change`: promoveringen
198	     fördubblade antalet tappade bildrutor i stället för att ta bort dem. */
199	  .ground{position:fixed;inset:0;z-index:0;pointer-events:none;contain:strict;
200	    /* 62 % svarar mot V3b:s opacity:.62 på tonlagret. */
201	    background-image:linear-gradient(
202	        color-mix(in srgb,var(--sc-canvas) 62%,transparent),
203	        color-mix(in srgb,var(--sc-canvas) 62%,transparent)),
204	      var(--ground-img);
205	    background-size:cover,cover;
206	    background-position:center center,center 40%;
207	    background-repeat:no-repeat,no-repeat;
208	    background-blend-mode:color,normal;
209	    filter:grayscale(1) contrast(1.08) brightness(.5);}
210	
211	  /* ============================================================ toppraden
212	     Låst nav: tunn topprad med ordmärke och kontakt som scrollar bort.
213	     position:absolute i stället för i flödet, så att den pinnade stagen börjar
214	     på y = 0 och folden inte tappar sina understa 50 px. */
215	  .topline{position:absolute;top:0;left:0;right:0;z-index:5;
216	    display:flex;align-items:center;justify-content:space-between;
217	    padding:16px var(--rail-x);}
218	  .topline::before{content:"";position:absolute;inset:0;z-index:-1;
219	    background:linear-gradient(180deg,rgba(6,7,9,.62) 0%,rgba(6,7,9,.34) 78%,rgba(6,7,9,0) 100%);}
220	  .topline-mark{font-weight:300;font-size:clamp(13px,1.6vw,17px);letter-spacing:.02em;color:#f4f2ef;}
221	  .topline-contact{font-weight:300;font-size:12px;letter-spacing:.04em;color:rgba(244,242,239,.84);
222	    text-decoration:none;border-bottom:1px solid transparent;
223	    transition:border-color .25s var(--ease),color .25s var(--ease);}
224	  .topline-contact:hover{color:#f4f2ef;border-color:currentColor;}
225	
226	  main{position:relative;z-index:1;}
227	
228	  /* ============================================================ HERO / stagen
229	     .sc-stage får sin position:sticky och sin höjd ur motorns egen CSS.
230	     Ingenting nedan sätter position, height eller overflow på stagen. */
231	  /* Innehållet centreras i stagen på ALLA bredder. Mätt i pixlar: vid
232	     1440x900 fyller folden stagen så när som på en pixel och centreringen
233	     ändrar ingenting, men vid 768x1024 låg 364 px död yta under underraden när
234	     innehållet var toppställt. Felet följer viewportens HÖJD, inte dess bredd,
235	     så regeln hör inte hemma i en breddbrytpunkt. */
236	  .hero-stage{display:flex;flex-direction:column;justify-content:center;
237	    padding:clamp(44px,5.6vh,64px) 0 clamp(14px,2.2vh,26px);}
238	
239	  .hero-head{padding:0 var(--rail-x);}
240	  /* Rubriken ligger på den mörka GRUNDEN, aldrig över plåtens ljuspöl
241	     (planhat: vikt 300 i stor grad ligger i fotots mörka parti). Scrimmen är
242	     bunden till rubrikens eget block och är ett syskonlager, aldrig ett
243	     ::before på ett element shoot.mjs döljer. */
244	  .hero-head::before{content:"";position:absolute;left:0;right:0;top:0;height:52vh;z-index:-1;
245	    background:linear-gradient(180deg,rgba(5,6,7,.58) 0%,rgba(5,6,7,.38) 62%,rgba(5,6,7,0) 100%);
246	    pointer-events:none;}
247	  /* Taket höjt 7rem -> 7.5rem, se BRIEF.md § decision ledger rättelse 3:
248	     vid 1440 band 7rem vid 112 px och kvoten mot kortbaksidans 80,6 px blev
249	     0,72, över målet 0,70. 7.5rem = 120 px ger 0,67 och baksidan 5,04x
250	     brödtexten. Golvet sänkt 2.6rem -> 2.2rem för 320 px, se NOTES.md § R2. */
251	  .hero-headline{font-family:var(--font);font-weight:300;
252	    font-size:clamp(2.2rem,9cqw,7.5rem);line-height:.96;letter-spacing:-.01em;
253	    color:#f7f5f0;max-width:15ch;text-wrap:balance;overflow-wrap:anywhere;min-width:0;}
