import io, sys, json
from PIL import Image
from playwright.sync_api import sync_playwright

URL="http://127.0.0.1:3321/tests/alunix-r8/runs/V3c/index.html"
SEL = ("h1,h2,h3,p,span,a,figcaption,.card-kicker,.card-services,.ledger-num,"
       ".price-row .label,.price-row .value,.cap-line,.topline-mark,.topline-contact")

BOXES = """(sel)=>{
  const out=[]; const seen=new Set();
  document.querySelectorAll(sel).forEach(el=>{
    if(el.closest('[inert],[aria-hidden="true"]')) return;
    const has=[...el.childNodes].some(n=>n.nodeType===3&&n.textContent.trim());
    if(!has) return;
    const r=el.getBoundingClientRect();
    if(r.width<4||r.height<4||r.top>innerHeight-2||r.bottom<2) return;
    const cs=getComputedStyle(el);
    if(parseFloat(cs.opacity)<0.99) return;
    const t=el.innerText.trim().slice(0,32).replace(/\\s+/g,' ');
    const key=t+cs.color; if(seen.has(key))return; seen.add(key);
    out.push({t, x:Math.max(0,r.left), y:Math.max(0,r.top), w:r.width, h:r.height,
              color:cs.color, size:parseFloat(cs.fontSize), weight:parseInt(cs.fontWeight)||400,
              sel:(el.className&&typeof el.className==='string')?('.'+el.className.trim().split(/\\s+/).join('.')):el.tagName.toLowerCase()});
  });
  return out;
}"""

HIDE = ("h1,h2,h3,p,span,a,figcaption,li,div{color:transparent!important;"
        "text-decoration-color:transparent!important;text-shadow:none!important}"
        "svg,hr{opacity:0!important}")

def lin(v):
    v/=255
    return v/12.92 if v<=0.03928 else ((v+0.055)/1.055)**2.4
def lum(px): return 0.2126*lin(px[0])+0.7152*lin(px[1])+0.0722*lin(px[2])
def parse(c):
    n=c[c.find('(')+1:c.find(')')].split(',')
    return [float(x) for x in n[:3]], (float(n[3]) if len(n)>3 else 1.0)

def run(pg, ytarget, label):
    pg.evaluate(f"window.scrollTo(0,{ytarget})"); pg.wait_for_timeout(1200)
    boxes=pg.evaluate(BOXES, SEL)
    handle=pg.add_style_tag(content=HIDE); pg.wait_for_timeout(400)
    plate=Image.open(io.BytesIO(pg.screenshot())).convert('RGB')
    pg.evaluate("(el)=>el.remove()", handle); pg.wait_for_timeout(200)
    rows=[]
    for b in boxes:
        x0,y0=int(b['x']),int(b['y']); x1,y1=int(b['x']+b['w']),int(b['y']+b['h'])
        crop=plate.crop((x0,y0,min(x1,plate.width),min(y1,plate.height)))
        px=list(crop.getdata())
        if not px: continue
        lums=sorted(lum(q) for q in px)
        fgc,alpha=parse(b['color'])
        # worst case: the ground pixel closest in luminance to the text
        fg=lum(fgc)
        worst=min(lums,key=lambda L: abs(L-fg))
        mean=sum(lums)/len(lums)
        def ratio(a,bl): 
            hi,lo=max(a,bl),min(a,bl); return (hi+0.05)/(lo+0.05)
        large = b['size']>=24 or (b['size']>=18.66 and b['weight']>=700)
        floor = 3 if large else 4.5
        rows.append((ratio(fg,worst), ratio(fg,mean), floor, b['size'], b['t'], b['sel'], b['color']))
    print(f"\n===== {label} (scrollY={ytarget})")
    for r in sorted(rows):
        mark='FAIL' if r[0]<r[2] else 'ok  '
        print(f"{mark} worst {r[0]:6.2f}:1  mean {r[1]:6.2f}:1  (floor {r[2]})  {int(r[3]):>3}px  {r[6]:<22} {r[4]!r}  {r[5][:40]}")

with sync_playwright() as p:
    b=p.chromium.launch()
    pg=b.new_page(viewport={'width':1440,'height':900})
    try: pg.goto(URL, wait_until='networkidle', timeout=60000)
    except Exception: pg.goto(URL, wait_until='load', timeout=60000)
    pg.wait_for_timeout(1500)
    H=pg.evaluate("document.documentElement.scrollHeight")
    print("scrollHeight",H)
    for frac,label in [(0.0,'s1 hero front'),(0.09,'s2 mid-flip'),(0.16,'s3 card back'),(0.30,'s4 thesis blue + giant paper'),(0.45,'s5 calyx + ledger paper'),(0.62,'s6 price dark + horai'),(0.78,'s6b'),(0.97,'s7 close')]:
        run(pg,int(H*frac),label)
    b.close()
