from playwright.sync_api import sync_playwright
URL="http://127.0.0.1:3321/tests/alunix-r8/runs/V3c/index.html"
JS="""()=>{const out=[];
 document.querySelectorAll('iframe').forEach(f=>{
  let n=f, chain=[];
  while(n && n!==document.documentElement){const cs=getComputedStyle(n);
    chain.push((n.className||n.tagName)+':op='+cs.opacity+' vis='+cs.visibility+' cp='+cs.clipPath.slice(0,20)+' tr='+cs.transform.slice(0,26));
    n=n.parentElement;}
  out.push({title:f.getAttribute('title'),src:f.getAttribute('src'),data:f.getAttribute('data-src'),chain:chain.slice(0,4)});});
 return out;}"""
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(viewport={'width':1440,'height':900})
    try: pg.goto(URL, wait_until='networkidle', timeout=60000)
    except Exception: pg.goto(URL, wait_until='load', timeout=60000)
    pg.wait_for_timeout(1800)
    import json
    print("--- scrollY 0"); print(json.dumps(pg.evaluate(JS),indent=1,ensure_ascii=False))
    # inert experiment
    pg.evaluate("document.querySelectorAll('.frame-wrap').forEach(w=>w.inert=true)")
    pg.evaluate("document.body.focus&&document.body.focus()")
    seq=[]
    for i in range(8):
        pg.keyboard.press("Tab"); pg.wait_for_timeout(70)
        d=None
        for fr in pg.frames:
            try: d=fr.evaluate("()=>{const e=document.activeElement;return (!e||e===document.body)?null:[e.tagName,e.className.slice&&e.className.slice(0,16),(e.getAttribute('title')||e.innerText||'').slice(0,26)]}")
            except Exception: d=None
            if d: break
        seq.append((d, pg.evaluate("window.scrollY")))
        if d is None: break
    print("--- tab order with .frame-wrap inert:")
    for s in seq: print("   ",s)
    b.close()
